using Saldo360.Api.Authentication;
using Saldo360.Application.Debts;
using Saldo360.Domain.Common;

namespace Saldo360.Api.Debts;
public static class FinancialDebtInstallmentEndpoints
{
 public static IEndpointRouteBuilder MapFinancialDebtInstallmentEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/families/{familyId:guid}/debts/{debtId:guid}/installments").RequireAuthorization();g.MapGet("/",List);g.MapPost("/",Create).AddEndpointFilter<ValidateCsrfTokenFilter>();g.MapGet("/{installmentId:guid}",Get);g.MapGet("/{installmentId:guid}/payments",Payments);g.MapPost("/{installmentId:guid}/payments",Pay).AddEndpointFilter<ValidateCsrfTokenFilter>();g.MapPost("/{installmentId:guid}/payments/{paymentId:guid}/cancel",Cancel).AddEndpointFilter<ValidateCsrfTokenFilter>();return app;}
 static async Task<IResult> List(Guid familyId,Guid debtId,CurrentUser u,FinancialDebtInstallmentService s,CancellationToken ct)=>await u.GetUserIdAsync(ct) is not{ } uid?Results.Unauthorized():await s.ListAsync(familyId,debtId,uid,ct) is var r&&!r.NotFound?Results.Ok(r.Items!.Select(Response.From)):Results.NotFound();
 static async Task<IResult> Create(Guid familyId,Guid debtId,InstallmentRequest? x,CurrentUser u,FinancialDebtInstallmentService s,CancellationToken ct){if(await u.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();var r=await s.CreateAsync(familyId,debtId,uid,x?.ToInput()??new(null,null,null,null,null,null,null),ct);return r.Access switch{DebtInstallmentAccess.Allowed=>Results.Created($"/api/families/{familyId}/debts/{debtId}/installments/{r.Installment!.Id}",Response.From(r.Installment)),DebtInstallmentAccess.Invalid=>Results.ValidationProblem(r.Errors!),DebtInstallmentAccess.Conflict=>Results.Conflict(new{title=r.Message}),_=>Results.NotFound()};}
 static async Task<IResult> Get(Guid familyId,Guid debtId,Guid installmentId,CurrentUser u,FinancialDebtInstallmentService s,CancellationToken ct)=>await u.GetUserIdAsync(ct) is not{ } uid?Results.Unauthorized():await s.ListAsync(familyId,debtId,uid,ct) is var r&&!r.NotFound&&r.Items!.FirstOrDefault(x=>x.Id==installmentId) is{ } x?Results.Ok(Response.From(x)):Results.NotFound();
 static async Task<IResult> Payments(Guid familyId,Guid debtId,Guid installmentId,CurrentUser u,FinancialDebtInstallmentService s,CancellationToken ct)=>await u.GetUserIdAsync(ct) is not{ } uid?Results.Unauthorized():await s.PaymentsAsync(familyId,debtId,installmentId,uid,ct) is{ } xs?Results.Ok(xs):Results.NotFound();
 static async Task<IResult> Pay(Guid familyId,Guid debtId,Guid installmentId,PaymentRequest? x,CurrentUser u,FinancialDebtInstallmentService s,CancellationToken ct){if(await u.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();var r=await s.PayAsync(familyId,debtId,installmentId,uid,x?.ToInput()??new(null,null,null,null,null,null,null,null),ct);return r.Access switch{DebtInstallmentAccess.Allowed=>Results.Ok(PaymentResponse.From(r.Payment!)),DebtInstallmentAccess.Invalid=>Results.ValidationProblem(r.Errors!),DebtInstallmentAccess.Conflict=>Results.Conflict(new{title=r.Message}),_=>Results.NotFound()};}
 static async Task<IResult> Cancel(Guid familyId,Guid debtId,Guid installmentId,Guid paymentId,CurrentUser u,FinancialDebtInstallmentService s,CancellationToken ct){if(await u.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();var ok=await s.CancelAsync(familyId,debtId,installmentId,paymentId,uid,ct);return ok?Results.Ok():Results.NotFound();}
 public sealed record InstallmentRequest(int? InstallmentNumber,DateOnly? DueDate,string? ScheduledAmount,string? PrincipalComponent,string? InterestComponent,string? InsuranceComponent,string? OtherChargesComponent){public InstallmentInput ToInput()=>new(InstallmentNumber,DueDate,ScheduledAmount,PrincipalComponent,InterestComponent,InsuranceComponent,OtherChargesComponent);}
 public sealed record PaymentRequest(string? OperationId,Guid? FinancialAccountId,DateOnly? PaymentDate,string? Amount,string? PrincipalPaid,string? InterestPaid,string? InsurancePaid,string? OtherChargesPaid){public PaymentInput ToInput()=>new(OperationId,FinancialAccountId,PaymentDate,Amount,PrincipalPaid,InterestPaid,InsurancePaid,OtherChargesPaid);}
 public sealed record Response(Guid Id,Guid FamilyId,Guid DebtId,int InstallmentNumber,DateOnly DueDate,string ScheduledAmount,string? PrincipalComponent,string? InterestComponent,string? InsuranceComponent,string? OtherChargesComponent,string PaidAmount,string RemainingAmount,string Status,DateTimeOffset CreatedAt){public static Response From(InstallmentDto x)=>new(x.Id,x.FamilyId,x.DebtId,x.InstallmentNumber,x.DueDate,Money.Format(x.ScheduledAmount),x.PrincipalComponent is{} a?Money.Format(a):null,x.InterestComponent is{} b?Money.Format(b):null,x.InsuranceComponent is{} c?Money.Format(c):null,x.OtherChargesComponent is{} d?Money.Format(d):null,Money.Format(x.PaidAmount),Money.Format(x.RemainingAmount),x.Status,x.CreatedAt);}
 public sealed record PaymentResponse(Guid Id,Guid InstallmentId,Guid FinancialAccountId,DateOnly PaymentDate,string Amount,string? PrincipalPaid,string? InterestPaid,Guid BankTransactionId,string OperationId,bool IsCancelled,DateTimeOffset CreatedAt){public static PaymentResponse From(PaymentDto x)=>new(x.Id,x.InstallmentId,x.FinancialAccountId,x.PaymentDate,Money.Format(x.Amount),x.PrincipalPaid is{} a?Money.Format(a):null,x.InterestPaid is{} b?Money.Format(b):null,x.BankTransactionId,x.OperationId,x.IsCancelled,x.CreatedAt);}
}
